WITH windowed AS MATERIALIZED (SELECT sp.request_id, sp.created_at, sp.blocks->2->>'text' AS instructions FROM system_prompts.session_prompts sp WHERE sp.lane = 'subagent' AND COALESCE(sp.subagent_persona, '') = '' AND sp.created_at >= NOW() - INTERVAL '7 days'), ranked AS (SELECT instructions, request_id, created_at, COUNT(*) OVER (PARTITION BY instructions)::bigint AS observation_count, ROW_NUMBER() OVER (PARTITION BY instructions ORDER BY created_at DESC, request_id DESC) AS rn FROM windowed) SELECT instructions, observation_count, created_at AS last_seen, request_id AS latest_request_id FROM ranked WHERE rn = 1 ORDER BY observation_count DESC, last_seen DESC LIMIT 50
